<script setup>
import { computed, ref, onMounted, onUnmounted } from 'vue'
import UiDialog from './UiDialog.vue'
import PaginationNav from './PaginationNav.vue'
import { activityRequest as request, activityJson as json } from '../lib/activities'
const rows = ref([]), tags = ref([]), jobs = ref([]), stage = ref('pending'), scope = ref(''), query = ref(''), page = ref(1)
const message = ref(''), error = ref(''), busy = ref(false), progress = ref(0), uploading = ref(false), selected = ref(null), form = ref(null), versionId = ref(''), port = ref(''), tagName = ref(''), confirmation = ref(null)
const fileInput = ref(null), tagEdits = ref({})
let timer, stopped = false, xhr, seenJobs = new Set()
const api = (path = '', options = {}) => request(path, options, true)
const collections = computed(() => rows.value.filter(row => row.kind === 'collection'))
const current = computed(() => rows.value.find(row => row.id === selected.value))
const currentVersion = computed(() => current.value?.versions.find(version => version.id === versionId.value))
const activeJobs = computed(() => jobs.value.filter(job => ['running', 'queued'].includes(job.status)))
const labels = { pending: '待发布', preview: '预览', published: '已发布', archived: '已归档', stopped: '已停止', running: '运行中', starting: '启动中', building: '构建中', ready: '已构建', failed: '失败', error: '出错' }
function location(row) { const titles = [], seen = new Set(); let id = row.parent_id; while (id && !seen.has(id)) { seen.add(id); const parent = rows.value.find(item => item.id === id); if (!parent) break; titles.unshift(parent.title); id = parent.parent_id } return titles.join(' / ') || '根目录' }
const list = computed(() => rows.value.filter(row => (stage.value === 'preview' ? row.state === 'preview' || row.preview_version_id : stage.value === 'pending' ? row.state === 'pending' || row.versions.some(v => v.state === 'pending') : row.state === 'published') && (stage.value !== 'published' || row.parent_id === (scope.value ? Number(scope.value) : null)) && `${row.title} ${row.identifier || ''} ${location(row)}`.toLocaleLowerCase().includes(query.value.trim().toLocaleLowerCase())).sort((a, b) => a.display_order - b.display_order || a.id - b.id))
const pages = computed(() => Math.max(1, Math.ceil(list.value.length / 15)))
const visible = computed(() => list.value.slice((page.value - 1) * 15, page.value * 15))
const parents = computed(() => collections.value.filter(row => { const seen = new Set(); let id = row.id; while (id && !seen.has(id)) { if (id === selected.value) return false; seen.add(id); id = rows.value.find(i => i.id === id)?.parent_id } return true }))
const dateInput = value => value ? new Date(Date.parse(value) - new Date(value).getTimezoneOffset() * 60000).toISOString().slice(0, 16) : ''
async function load(first = false) {
  try {
    const result = await api(versionId.value ? `?version=${encodeURIComponent(versionId.value)}` : ''); if (stopped) return
    rows.value = result.data; if (first || !document.activeElement?.closest('.tag-pool')) tags.value = result.tags; jobs.value = result.jobs; page.value = Math.min(page.value, pages.value)
    for (const tag of result.tags) if (tagEdits.value[tag.id] === undefined) tagEdits.value[tag.id] = tag.name
    if (scope.value && !rows.value.some(row => row.id === Number(scope.value))) scope.value = ''
    if (!port.value && currentVersion.value?.backend_port) syncPort()
    for (const job of result.jobs) if (!seenJobs.has(job.id) && ['failed', 'completed'].includes(job.status)) { seenJobs.add(job.id); if (!first && job.kind !== 'schedule') { if (job.status === 'failed') error.value = job.message; else message.value = job.message } }
  } catch (cause) { if (!stopped) error.value = cause.message }
}
function edit(row) { selected.value = row.id; form.value = { ...row, tags: [...row.tags], starts_at: dateInput(row.starts_at), ends_at: dateInput(row.ends_at) }; versionId.value = row.preview_version_id || row.versions.find(v => v.state === 'pending')?.id || row.published_version_id || row.versions[0]?.id || ''; error.value = ''; syncPort() }
function syncPort() { port.value = currentVersion.value?.backend_port || '' }
async function perform(action, notice) { if (busy.value || uploading.value) return; busy.value = true; error.value = ''; message.value = ''; try { await action(); await load(); if (notice) message.value = notice } catch (cause) { error.value = cause.message } finally { busy.value = false } }
async function save() { await api(`/items/${selected.value}`, json('PUT', form.value)) }
function saveForm() { perform(save, '活动设置已保存') }
function setState(state) { perform(async () => { await save(); const result = await api(`/items/${selected.value}/state`, json('POST', { state, versionId: versionId.value })); message.value = result.data.message }, '已提交，构建与发布进度见任务列表') }
function create(kind) { perform(async () => { const result = await api('/items', json('POST', { kind, title: kind === 'collection' ? '新活动合集' : '新外部活动', external_url: kind === 'activity' ? 'https://example.com/' : '', parent_id: scope.value ? Number(scope.value) : null, tags: [], entry_label: '进入活动' })); await load(); edit(rows.value.find(row => row.id === result.id)) }, '已创建，请完善信息并保存') }
async function upload(files) {
  const file = files?.[0]; if (!file || busy.value || uploading.value) return
  if (!/\.zip$/i.test(file.name) || file.size > 2 * 1024 ** 3) { error.value = '请选择不超过 2GB 的活动 ZIP 发布包'; return }
  uploading.value = true; progress.value = 0; error.value = ''; message.value = ''
  const data = new FormData(); data.append('file', file)
  try {
    const result = await new Promise((resolve, reject) => {
      xhr = new XMLHttpRequest(); xhr.open('POST', '/api/admin/activities/upload'); xhr.withCredentials = true
      xhr.upload.onprogress = event => { if (event.lengthComputable) progress.value = Math.round(event.loaded / event.total * 100) }
      xhr.onload = () => { try { const result = JSON.parse(xhr.responseText); if (xhr.status >= 400 || !result.success) reject(new Error(result.message || '上传失败')); else resolve(result) } catch { reject(new Error('上传失败，请检查服务器上传限制')) } }
      xhr.onerror = () => reject(new Error('上传失败，请检查网络')); xhr.onabort = () => reject(new Error('上传已取消')); xhr.send(data)
    })
    await load(); if (stopped) return; edit(rows.value.find(row => row.id === result.data.itemId)); versionId.value = result.data.versionId; syncPort(); stage.value = 'pending'; page.value = 1; message.value = '发布包已通过校验，请完善设置后进入预览'
  } catch (cause) { if (!stopped) error.value = cause.message } finally { uploading.value = false; xhr = null; if (fileInput.value) fileInput.value.value = '' }
}
function changePort() { perform(() => api(`/items/${selected.value}/versions/${versionId.value}/port`, json('POST', { port: Number(port.value) })), '端口检查通过，正在更新后端') }
function confirmDelete(row, version) { confirmation.value = { row, version, text: version ? `删除版本 ${version.version} 的代码包、容器和镜像？该活动的共享存档会保留。` : `移除“${row.title}”？其全部版本、代码包、容器、镜像和活动存档都会删除。合集需先清空成员。` } }
function remove() { const target = confirmation.value; perform(async () => { await api(`/items/${target.row.id}${target.version ? `/versions/${target.version.id}` : ''}`, { method: 'DELETE' }); confirmation.value = null; if (!target.version) { selected.value = null; form.value = null } }, '已提交清理任务') }
function move(row, direction) { perform(async () => { const siblings = rows.value.filter(item => item.state === 'published' && item.parent_id === row.parent_id).sort((a, b) => a.display_order - b.display_order || a.id - b.id), index = siblings.findIndex(item => item.id === row.id), next = index + direction; if (next < 0 || next >= siblings.length) return; [siblings[index], siblings[next]] = [siblings[next], siblings[index]]; await api('/order', json('POST', { parent_id: row.parent_id, ids: siblings.map(item => item.id) })) }, '显示顺序已更新') }
function addTag() { perform(async () => { await api('/tags', json('POST', { name: tagName.value })); tagName.value = '' }, '标签已添加') }
function renameTag(tag) { perform(() => api(`/tags/${tag.id}`, json('PUT', { name: tagEdits.value[tag.id] })), '标签已更新') }
function deleteTag(tag) { perform(async () => { await api(`/tags/${tag.id}`, { method: 'DELETE' }); if (form.value) form.value.tags = form.value.tags.filter(id => id !== tag.id) }, '标签已移除') }
async function cover(event) { const file = event.target.files?.[0]; if (!file) return; perform(async () => { const data = new FormData(); data.append('file', file); const response = await fetch('/api/admin/upload', { method: 'POST', body: data, credentials: 'same-origin' }), result = await response.json(); if (!result.success) throw new Error(result.message); form.value.cover = result.url; await save() }, '封面已上传并保存'); event.target.value = '' }
function changeStage(value) { stage.value = value; page.value = 1 }
onMounted(async () => { await load(true); if (!stopped) timer = setInterval(() => { if (!uploading.value && !busy.value) load() }, 3000) })
onUnmounted(() => { stopped = true; clearInterval(timer); xhr?.abort() })
</script>
<template>
  <section class="plaza-admin">
    <header class="manager-heading"><div><h2>活动发布</h2><p>上传网页包，或嵌入外部网站。新版预览完成后再公开发布。</p></div><a href="/activities" target="_blank" rel="noopener" class="ghost-button">查看广场 ↗</a></header>
    <p v-if="error" class="manager-notice error" role="alert">{{ error }}</p><p v-if="message" class="manager-notice" role="status">{{ message }}</p>
    <div class="surface upload-panel" @dragover.prevent @drop.prevent="upload($event.dataTransfer.files)"><div><strong>{{ uploading ? `正在上传 ${progress}%` : '上传活动发布包' }}</strong><p>{{ uploading && progress === 100 ? '上传完成，正在校验包内文件…' : '拖入 ZIP 或点击选择。同一标识符的包会成为新版本。' }}</p></div><div class="actions"><input ref="fileInput" type="file" accept=".zip" hidden :disabled="busy || uploading" @change="upload($event.target.files)" /><button class="primary-button" :disabled="busy || uploading" @click="fileInput?.click()">选择发布包</button><button class="ghost-button" :disabled="busy || uploading" @click="create('activity')">+ 外部网站</button><button class="ghost-button" :disabled="busy || uploading" @click="create('collection')">+ 活动合集</button></div></div>
    <details class="surface tag-pool"><summary>活动标签池</summary><div class="tag-list"><div v-for="tag in tags" :key="tag.id" class="actions"><input v-model="tagEdits[tag.id]" maxlength="40" aria-label="标签名称" /><button class="ghost-button" :disabled="busy" @click="renameTag(tag)">保存</button><button class="ghost-button" :disabled="busy" @click="deleteTag(tag)">移除</button></div><form class="actions" @submit.prevent="addTag"><input v-model="tagName" placeholder="新标签名称" maxlength="40" required /><button class="primary-button" :disabled="busy">添加</button></form></div></details>
    <div v-if="activeJobs.length" class="surface task-panel" role="status"><h3>运行任务</h3><p v-for="job in activeJobs" :key="job.id">{{ job.status === 'queued' ? '排队中' : '执行中' }} · {{ job.message }}</p></div>
    <div class="list-tools"><nav class="stages"><button v-for="state in ['pending', 'preview', 'published']" :key="state" :class="{ active: stage === state }" @click="changeStage(state)">{{ labels[state] }}</button></nav><input v-model="query" type="search" placeholder="搜索名称、标识符或合集" aria-label="搜索活动" @input="page = 1" /><select v-if="stage === 'published'" v-model="scope" aria-label="显示位置" @change="page = 1"><option value="">根目录排序</option><option v-for="collection in collections" :key="collection.id" :value="String(collection.id)">{{ location(collection) }} / {{ collection.title }}</option></select></div>
    <div class="manager-grid"><section class="activity-rows"><p v-if="!visible.length" class="surface empty">此列表暂时没有内容。</p><article v-for="row in visible" :key="row.id" class="surface activity-row" :class="{ selected: selected === row.id }"><div class="row-title"><span class="kind">{{ row.kind === 'collection' ? '合集' : row.source === 'external' ? '外链' : '网页包' }}</span><h3>{{ row.title }}</h3></div><small>{{ location(row) }}<template v-if="row.identifier"> · {{ row.identifier }}</template></small><p v-if="row.preview_version_id">新版预览中</p><div class="actions"><button class="ghost-button" @click="edit(row)">编辑 / 版本</button><template v-if="stage === 'published'"><button class="ghost-button" :disabled="busy" aria-label="上移" @click="move(row, -1)">↑</button><button class="ghost-button" :disabled="busy" aria-label="下移" @click="move(row, 1)">↓</button><button v-if="row.kind === 'collection'" class="ghost-button" @click="scope = String(row.id); page = 1">整理内部顺序</button></template><button class="ghost-button" :disabled="busy" @click="confirmDelete(row)">移除</button></div></article><PaginationNav v-if="pages > 1" :page="page" :total-pages="pages" @change="page = $event" /></section>
    <section v-if="form && current" class="surface activity-editor"><header class="editor-heading"><h3>{{ current.kind === 'collection' ? '合集设置' : '活动设置' }}</h3><button class="ghost-button" @click="selected = null; form = null">收起</button></header><form @submit.prevent="saveForm">
      <label>名称<input v-model="form.title" required maxlength="150" /></label><label>位置<select v-model="form.parent_id"><option :value="null">根目录</option><option v-for="parent in parents" :key="parent.id" :value="parent.id">{{ location(parent) }} / {{ parent.title }}</option></select></label><label>简介<textarea v-model="form.summary" rows="3" maxlength="5000"></textarea></label><label>封面地址（选填）<input v-model="form.cover" /></label><label>上传封面<input type="file" accept="image/*" :disabled="busy" @change="cover" /></label><img v-if="form.cover" :src="form.cover" alt="活动封面预览" class="cover-preview" /><fieldset><legend>标签（选填）</legend><label v-for="tag in tags" :key="tag.id" class="check"><input v-model="form.tags" type="checkbox" :value="tag.id" />{{ tag.name }}</label><small v-if="!tags.length">先在上方添加标签。</small></fieldset>
      <template v-if="current.kind === 'activity'"><label v-if="current.source === 'external'">外部 URL<input v-model="form.external_url" type="url" required /></label><label>入口文案<input v-model="form.entry_label" required maxlength="100" /></label><label class="check"><input v-model="form.pause_music" type="checkbox" />进入时自动暂停主站音乐</label><label class="check"><input v-model="form.login_required" type="checkbox" />登录后才能进入</label><label>活动类型<select v-model="form.schedule"><option value="permanent">常驻活动</option><option value="timed">限时活动</option></select></label><div v-if="form.schedule === 'timed'" class="date-fields"><label>开始时间<input v-model="form.starts_at" type="datetime-local" required /></label><label>结束时间<input v-model="form.ends_at" type="datetime-local" required /></label></div><label v-if="current.versions.some(v => v.backend_enabled)">后端环境变量（JSON）<textarea v-model="form.backend_env" spellcheck="false" rows="4" placeholder='{"BOT_TOKEN":"…"}'></textarea><small>仅传给此活动后端，不会提供给网页或 SDK。</small></label></template>
      <button class="primary-button" :disabled="busy || uploading">保存设置</button>
    </form>
    <section v-if="current.versions.length" class="version-panel"><h3>版本管理</h3><label>当前操作版本<select v-model="versionId" @change="syncPort"><option v-for="version in current.versions" :key="version.id" :value="version.id">{{ version.version }} · {{ labels[version.state] }}</option></select></label><template v-if="currentVersion"><p v-if="currentVersion.backend_enabled && currentVersion.backend_port">实际映射端口：{{ currentVersion.backend_port }}</p><p>{{ currentVersion.backend_enabled ? '独立后端 · ' + (labels[currentVersion.build_status] || currentVersion.build_status) + ' · ' + labels[currentVersion.runtime_status] : '纯网页 · 无需容器' }}</p><form v-if="currentVersion.backend_enabled && currentVersion.backend_port" class="actions" @submit.prevent="changePort"><label>宿主机端口<input v-model="port" type="number" min="40000" max="65535" required /></label><button class="ghost-button" :disabled="busy">修改端口</button></form><p v-if="currentVersion.error" class="error">{{ currentVersion.error }}</p><details v-if="currentVersion.logs.length"><summary>构建 / 运行日志</summary><pre>{{ currentVersion.logs.map(line => `${line.time}\n${line.text}`).join('\n') }}</pre></details><button v-if="![current.published_version_id, current.preview_version_id].includes(versionId)" class="ghost-button" :disabled="busy" @click="confirmDelete(current, currentVersion)">删除此版本</button></template></section>
    <footer class="publish-actions"><button class="ghost-button" :disabled="busy || uploading" @click="setState('preview')">保存并进入预览</button><RouterLink v-if="current.state !== 'pending' && current.kind === 'activity' && (current.source === 'external' || current.preview_version_id === versionId)" class="ghost-button" :to="{ path: `/activities/play/${current.id}`, query: { preview: '1', version: versionId || undefined } }" target="_blank">打开预览 ↗</RouterLink><button class="primary-button" :disabled="busy || uploading || current.kind === 'activity' && (current.source === 'package' ? current.preview_version_id !== versionId && current.published_version_id !== versionId : current.state === 'pending')" @click="setState('published')">保存并发布</button><button v-if="current.state !== 'pending'" class="ghost-button" :disabled="busy" @click="setState('pending')">撤回至待发布</button></footer><small class="editor-note">预览不受开放时间和登录限制。更换版本不会清除活动的共享存档。</small>
    </section></div>
    <UiDialog :open="!!confirmation" title="确认移除" :busy="busy" @close="confirmation = null"><p>{{ confirmation?.text }}</p><div class="actions"><button class="ghost-button" :disabled="busy" @click="confirmation = null">取消</button><button class="primary-button" :disabled="busy" @click="remove">确认移除</button></div></UiDialog>
  </section>
</template>
<style scoped>
.manager-heading,.editor-heading { display:flex; align-items:center; justify-content:space-between; gap:16px; }.manager-heading h2 { margin:0; }.manager-heading p,.upload-panel p { color:var(--muted); line-height:1.7; }.manager-notice { padding:15px 20px; background:var(--accent-soft); border-radius:5px; }.error { color:var(--danger, #b64b39); overflow-wrap:anywhere; }.upload-panel { padding:24px; display:flex; justify-content:space-between; align-items:center; gap:20px; margin-bottom:25px; }.actions { display:flex; flex-wrap:wrap; align-items:center; gap:8px; }.tag-pool { padding:18px 24px; margin-bottom:24px; }.tag-pool summary { cursor:pointer; font-weight:700; }.tag-list { display:grid; gap:12px; margin-top:20px; }.tag-list input { flex:1; width:100px; }.task-panel { padding:16px 24px; margin-bottom:24px; }.task-panel h3 { margin:0; }.task-panel p { color:var(--muted); }.list-tools { display:flex; align-items:center; gap:12px; flex-wrap:wrap; margin-bottom:22px; }.list-tools > select { width:auto; min-width:200px; }.list-tools > input { flex:1; min-width:180px; }.stages { display:flex; gap:6px; }.stages button { background:var(--paper-deep); color:var(--ink); border:0; border-radius:4px; padding:10px 16px; font-weight:700; }.stages button.active { background:var(--accent); color:var(--paper); }.manager-grid { display:grid; grid-template-columns:minmax(230px, 2fr) minmax(340px, 3fr); gap:26px; align-items:start; }.manager-grid:has(> :only-child) { grid-template-columns:1fr; }.activity-rows { display:grid; gap:16px; }.activity-row { padding:20px; }.activity-row.selected { background:var(--accent-soft); }.row-title { display:flex; align-items:center; gap:10px; margin-bottom:8px; }.row-title h3 { margin:0; font-size:18px; overflow-wrap:anywhere; }.kind { font-size:11px; flex:none; background:var(--paper-deep); padding:4px 7px; border-radius:3px; }.activity-row small { color:var(--muted); }.activity-row .actions { margin-top:17px; }.activity-row p { color:var(--accent); font-size:13px; }.activity-editor { padding:25px; min-width:0; }.activity-editor form { display:grid; gap:15px; }.activity-editor label { display:grid; gap:8px; font-size:13px; font-weight:700; }.activity-editor label small { color:var(--muted); font-weight:400; line-height:1.7; }.activity-editor .check { display:inline-flex; align-items:center; margin:5px 12px 5px 0; gap:8px; }.check input { width:auto; }.date-fields { display:flex; gap:12px; flex-wrap:wrap; }.date-fields label { flex:1; }fieldset { border:0; background:var(--paper-deep); border-radius:4px; padding:15px; }legend { font-size:13px; }.cover-preview { width:100%; max-height:180px; object-fit:cover; border-radius:4px; }.version-panel { margin-top:28px; padding-top:20px; border-top:2px solid var(--paper-deep); }.version-panel pre { max-height:300px; overflow:auto; white-space:pre-wrap; overflow-wrap:anywhere; background:var(--paper-deep); padding:15px; font-size:12px; }.publish-actions { display:flex; flex-wrap:wrap; gap:10px; margin-block:25px 15px; }.editor-note { color:var(--muted); line-height:1.8; }.empty { padding:30px; }input,textarea,select { width:100%; min-width:0; padding:10px 12px; border:0; border-radius:4px; background:var(--paper-deep); color:var(--ink); font:inherit; }button { cursor:pointer; }button:disabled { cursor:wait; opacity:.55; }
@media(max-width:900px) { .manager-grid { grid-template-columns:1fr; }.upload-panel { align-items:flex-start; flex-direction:column; }.activity-editor { padding:20px; } }
</style>
